import {Skitter} from './skitter.js?v=473';
// Reuses the live drone, projectile, damage and wreck systems; no mission spawning.
export class CombatTesting {
 constructor(scene,damage,{getHeroes,readConfig,bastionConfig,...options}){
  this.bastion=new BastionTesting(scene,damage,bastionConfig,{getHeroes,arenaBounds:COMBAT_ARENA.movementBounds,onEvent:options.onEvent,onDeathBlast:options.onBastionDeathBlast,traceProjectile:(a,b,r)=>options.trace(a,b,'bastion',r),onProjectileImpact:options.onBastionImpact,rainLanding:options.rainLanding,onRainImpact:options.onBastionRainImpact});this.flightDrones=options.drone?Array.from({length:2},(_,i)=>new CombatDrone(scene,damage,{
   ...options.drone,id:'combat-drone-'+i,bounds:COMBAT_ARENA.movementBounds,onEvent:options.onEvent
  })):[];this.getHeroes=getHeroes;this.readConfig=readConfig;this.targets=new Map();this.energyEffects=new RaiderEnergyEffects(scene);
  this.basic=Array.from({length:7},(_,i)=>new SpiderBruiser(scene,damage,{...options,id:'evac-raider-test-'+i,spawnPosition:{x:COMBAT_ARENA.enemyCorner.x+(i-3)*7*COMBAT_ARENA.formationScale,y:.1,z:COMBAT_ARENA.enemyCorner.z+14*COMBAT_ARENA.formationScale},getTargets:()=>this.heroUnits(),initialCooldown:3+i*.2,energyEffects:this.energyEffects,onEvent:()=>{}}));
  this.experimental=['aegis','scythe'].flatMap((type,row)=>Array.from({length:3},(_,i)=>new ExperimentalRobot(scene,damage,{...options,type,id:'evac-raider-'+type+'-'+i,spawnPosition:{x:COMBAT_ARENA.enemyCorner.x+(i-1)*7*COMBAT_ARENA.formationScale,y:.1,z:COMBAT_ARENA.enemyCorner.z+(14+row*8)*COMBAT_ARENA.formationScale},getTargets:()=>this.heroUnits(),initialCooldown:1+i*.7,energyEffects:this.energyEffects,onEvent:()=>{}})));this.mireguards=Array.from({length:COMBAT_ARENA.mireguardSquads.length*COMBAT_ARENA.mireguardSquadSize},(_,i)=>new Mireguard(scene,damage,{...options,id:'evac-raider-mireguard-'+i,getTargets:()=>this.heroUnits(),energyEffects:this.energyEffects}));this.ronin=new AstraRonin(scene,damage,{...options,id:"evac-raider-ronin",onBuildingStrike:options.onRoninBuildingStrike,getTargets:()=>this.heroUnits(),energyEffects:this.energyEffects});this.sentinelFX=new SentinelFX(scene);this.sentinels=Array.from({length:3},(_,i)=>new AssaultSentinel(scene,damage,{...options,id:'evac-raider-sentinel-test-'+i,spawnPosition:{x:(i-1)*9,y:.1,z:-4},getTargets:()=>this.heroUnits(),initialCooldown:1.2+i*.5,energyEffects:this.energyEffects,fx:this.sentinelFX,sound:options.sound,onSlam:options.onSentinelSlam,blockers:()=>this.members,onEvent:()=>{}}));// Skitters need the private quadruped asset; without it the preset spawns nothing.
  this.skitters=options.skitterModel?Array.from({length:3},(_,i)=>new Skitter(scene,damage,{...options,id:'evac-raider-skitter-'+i,getTargets:()=>this.heroUnits(),energyEffects:this.energyEffects,peers:()=>this.skitters,onEvent:()=>{}})):[];
  this.members=[this.ronin,...this.basic,...this.experimental,...this.mireguards,...this.sentinels,...this.skitters];
  this.pyroclast=new Pyroclast(scene,damage,{getTargets:()=>this.heroUnits(),trace:(a,b,owner,r)=>options.trace?.(a,b,owner,r),visible:options.visible,rainLanding:options.rainLanding,onImpact:options.onPyroclastImpact,onDeath:options.onDeath,onEvent:options.onEvent});
 }
 heroUnits(){return this.getHeroes().map((h,i)=>{let u=this.targets.get(i);if(!u){u={id:'hero-target-'+i,kind:'hero',entity:h};this.targets.set(i,u);}u.alive=!!h?.enabled;u.dashPhased=!!(h?.dash?.active||h?.motion?.dash);u.shapes=u.alive?[{center:h.root.position.clone().add(new THREE.Vector3(0,1.4,0)),half:{x:.5,y:1,z:.5},rotation:h.root.quaternion.clone()}]:[];return u;}).filter(u=>u.alive&&!u.dashPhased);}
 reset(){const config=this.readConfig();this.walkerEnabled=!!config.walker&&config.preset!=='bastion';this.bastion.reset(config.preset==='bastion');this.preset=config.preset||'basic';this.ronin.setModelVariant(config.roninModel||'original');this.count=Math.max(0,Math.min(7,Number(config.drones)||0));for(const r of this.members)r.reset();for(const drone of this.flightDrones)drone.reset();this.pyroclast.reset();if(this.preset==='pyroclast')this.pyroclast.spawn();
  if(this.preset==='drone'||this.preset==='drone-pair'){
   const positions=this.preset==='drone'?[[0,80]]:[[0,76],[9,87]];
   positions.forEach(([x,z],i)=>this.flightDrones[i]?.spawn({x,y:COMBAT_DRONE.flight.altitude,z}));
  }this.energyEffects.reset();if(['bastion','drone','drone-pair','pyroclast'].includes(this.preset))this.activeMembers=[];else if(this.preset==='ronin')this.activeMembers=[this.ronin];else if(this.preset.startsWith('mireguard'))this.activeMembers=this.mireguards.slice(0,this.preset==='mireguard-3'?this.mireguards.length:Number(this.preset.split('-')[1])||1);else if(this.preset==='mixed')this.activeMembers=this.experimental.filter(r=>!r.id.endsWith('-2'));else if(this.preset==='basic')this.activeMembers=this.basic.slice(0,this.count);else if(this.preset.startsWith('sentinel'))this.activeMembers=this.sentinels.slice(0,Number(this.preset.split('-')[1])||1);else if(this.preset.startsWith('skitter'))this.activeMembers=this.skitters.slice(0,Number(this.preset.split('-')[1])||1);else{const[type,n]=this.preset.split('-');this.activeMembers=this.experimental.filter(r=>r.type===type).slice(0,Number(n)||1);}this.count=this.activeMembers.length;for(const [i,r]of this.activeMembers.entries()){const columns=Math.min(3,this.activeMembers.length),rows=Math.ceil(this.activeMembers.length/3),p={x:(i%3-(columns-1)/2)*(this.preset.startsWith('mireguard')?16:8),y:.1,z:(Math.floor(i/3)-(rows-1)/2)*8};if(this.preset==='mireguard-3'){const size=COMBAT_ARENA.mireguardSquadSize,local=i%size,squad=COMBAT_ARENA.mireguardSquads[Math.floor(i/size)],spacing=COMBAT_ARENA.mireguardSquadSpacing;p.x=squad.x+(local%2-(Math.min(2,size)-1)/2)*spacing;p.z=squad.z+(Math.floor(local/2)-(Math.ceil(size/2)-1)/2)*spacing;r.squad=Math.floor(i/size);}else r.squad=null;r.spawnPosition=p;r.root.position.set(p.x,p.y,p.z);r.spawn();r.sync();}}
 update(dt,time){this.bastion.update(dt);this.pyroclast.update(dt,time);this.sentinelFX.update(dt);for(const r of this.members)r.update(dt,time);this.energyEffects.update(dt,this.bolts);if(this.flightDrones.some(d=>d.spawned)){const targets=this.heroUnits();for(const drone of this.flightDrones)drone.update(dt,targets);}}
 syncWrecks(){for(const r of this.members)r.syncWrecks();for(const drone of this.flightDrones)drone.syncWrecks();}
 disable(unit){if(unit===this.bastion.boss.combatUnit){this.bastion.boss.defeat();return true;}if(unit===this.pyroclast.combatUnit){this.pyroclast.destroy();return true;}const r=[...this.members,...this.flightDrones].find(r=>r.combatUnit===unit);if(!r)return false;r.destroy();return true;}
 getTarget(){if(this.bastion.enabled&&this.bastion.boss.combatUnit.alive)return this.bastion.boss;if(this.pyroclast.combatUnit?.alive)return this.pyroclast;return this.flightDrones.find(r=>r.combatUnit?.alive)||this.members.find(r=>r.combatUnit?.alive)||null;}
 get bolts(){return this.members.flatMap(r=>r.bolts);}
 diagnostics(){return{pyroclast:this.pyroclast.diagnostics(),bastion:this.bastion.diagnostics(),walker:this.walkerEnabled,drones:this.count,aliveDrones:this.members.filter(r=>r.combatUnit?.alive).length,preset:this.preset,flightDrones:this.flightDrones.filter(d=>d.spawned).map(d=>d.diagnostics()),members:(this.activeMembers||[]).map(r=>r.diagnostics())};}
}
